SELECT DATE_TRUNC('month', TRY_CAST(din_programacaodia AS TIMESTAMP)) AS mes, cod_subsistema,
  SUM(TRY_CAST(val_ger_hidraulica AS DOUBLE) + TRY_CAST(val_ger_pch AS DOUBLE) + TRY_CAST(val_ger_termica AS DOUBLE) + TRY_CAST(val_ger_eolica AS DOUBLE) + TRY_CAST(val_ger_solar AS DOUBLE)) AS geracao_total_mwmed
FROM {source}
WHERE EXTRACT(YEAR FROM TRY_CAST(din_programacaodia AS TIMESTAMP)) = {year}
GROUP BY 1, 2
ORDER BY 1, 2

SELECT DATE_TRUNC('month', CAST(din_programacaodia AS DATE)) AS mes, cod_subsistema,
  SUM((TRY_CAST(val_geracao_renovavel AS DOUBLE) + TRY_CAST(val_geracao_hidraulica AS DOUBLE) + TRY_CAST(val_geracao_termica AS DOUBLE)) * 0.5) / 1000 AS geracao_gwh
FROM {source}
WHERE EXTRACT(YEAR FROM CAST(din_programacaodia AS DATE)) = {year}
GROUP BY 1, 2
ORDER BY 1, 2

